    public static function getIcon(string $taxonomyName): array
    {
        $slug = Str::slug($taxonomyName);
        
        foreach (self::$iconMap as $key => $iconData) {
            if (Str::contains($slug, $key)) {
                return $iconData;
            }
        }
        
        return [
            'icon' => 'M4 5a1 1 0 011-1h14a1 1 0 011 1v2a1 1 0 01-1 1H5a1 1 0 01-1-1V5zM4 13a1 1 0 011-1h6a1 1 0 011 1v6a1 1 0 01-1 1H5a1 1 0 01-1-1v-6zM16 13a1 1 0 011-1h2a1 1 0 011 1v6a1 1 0 01-1 1h-2a1 1 0 01-1-1v-6z',
            'color' => '#6366f1',
        ];
    }

    public static function renderIcon(string $taxonomyName, string $size = 'w-6 h-6'): string
    {
        $iconData = self::getIcon($taxonomyName);
        
        return '<svg class="' . $size . '" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="' . $iconData['icon'] . '"/>
        </svg>';
    }
